import {concepts,periodIds} from './domain.mjs';
// Anonymized editorial syntheses of the supplied interviews, Madrid.
// No names, exact birth years, occupations, source URLs or raw transcripts.
// Associations stay in the period chosen by the interviewee, even if anachronistic.
const list=s=>s?s.split('|'):[];
function row(memory,keywords,events,capsule,association,feeling,one,extra={}){
 return {memory,keywords:concepts(list(keywords)),events:list(events),capsule:list(capsule),association,feeling,one,...extra};
}
function person(id,generation,capsule,rows,general){return {id,generation,synthetic:false,origin:'interview',capsule:list(capsule),periodData:Object.fromEntries(periodIds.map((p,i)=>[p,rows[i]])),general};}
